import unittest
from workload import trial, equivalent


class Part1(unittest.TestCase):
    def test_1_transpose_offsets(self):
        args = [[2, 2], [1, 2], 0]
        expected = [0, 2, 1, 3]
        actual = trial('view_offsets.view_offsets', args)
        self.assertTrue(equivalent(actual, expected), (actual, expected))

    def test_2_reverse_offsets(self):
        args = [[3], [-1], 2]
        expected = [2, 1, 0]
        actual = trial('view_offsets.view_offsets', args)
        self.assertTrue(equivalent(actual, expected), (actual, expected))


